namespace sv_31578d42d1c04c53bf3fc92de3808ed5.Services;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@page "/board"
@using sv_31578d42d1c04c53bf3fc92de3808ed5.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h1 class="mb-3">Kanban Board</h1>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-2 mb-3">
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold">Total</div>
                    <div class="fs-4">@_tasks.Count</div>
                </div>
            </div>
        </div>
        @foreach (var col in _columns)
        {
            <div class="col">
                <div class="card text-center">
                    <div class="card-body py-2">
                        <div class="fw-bold">@col</div>
                        <div class="fs-4">@GetColumnTasks(col).Count</div>
                    </div>
                </div>
            </div>
        }
        <div class="col">
            <div class="card text-center border-danger">
                <div class="card-body py-2">
                    <div class="fw-bold text-danger">Overdue</div>
                    <div class="fs-4 text-danger">@_tasks.Count(t => t.DueDate < DateTime.Today)</div>
                </div>
            </div>
        </div>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchQuery" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row g-3">
        @for (var i = 0; i < _columns.Length; i++)
        {
            var colIndex = i;
            var colName = _columns[colIndex];
            var columnTasks = GetFilteredColumnTasks(colName);

            <div class="col-md-4">
                <div class="card">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <h5 class="mb-0">@colName</h5>
                        <span class="badge bg-secondary">@columnTasks.Count</span>
                    </div>
                    <div class="card-body" style="min-height: 200px;">
                        @foreach (var task in columnTasks)
                        {
                            <div class="card mb-2">
                                <div class="card-body p-2">
                                    <div class="fw-bold">@task.Title</div>
                                    <div class="text-muted small">@task.Assignee</div>
                                    <div class="d-flex justify-content-between align-items-center mt-1">
                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="d-flex justify-content-between mt-2">
                                        @if (colIndex > 0)
                                        {
                                            var leftStatus = _columns[colIndex - 1];
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    disabled="@_movingTaskId.HasValue"
                                                    @onclick="() => MoveTaskAsync(task.Id, leftStatus)">
                                                &larr; Move Left
                                            </button>
                                        }
                                        else
                                        {
                                            <span></span>
                                        }
                                        @if (colIndex < _columns.Length - 1)
                                        {
                                            var rightStatus = _columns[colIndex + 1];
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    disabled="@_movingTaskId.HasValue"
                                                    @onclick="() => MoveTaskAsync(task.Id, rightStatus)">
                                                Move Right &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        <!-- Add Task Form -->
                        @if (_addingToColumn == colName)
                        {
                            <div class="card border-primary mt-2">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Title" @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Assignee" @bind="_newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-2"
                                           @bind="_newDueDate" />
                                    @if (_addError is not null)
                                    {
                                        <div class="text-danger small mb-1">@_addError</div>
                                    }
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-sm btn-primary" disabled="@_saving"
                                                @onclick="SaveNewTaskAsync">
                                            @if (_saving)
                                            {
                                                <span class="spinner-border spinner-border-sm me-1"></span>
                                            }
                                            Save
                                        </button>
                                        <button class="btn btn-sm btn-outline-secondary" disabled="@_saving"
                                                @onclick="CancelAdd">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-primary w-100 mt-2"
                                    @onclick="() => StartAdd(colName)">
                                + Add Task
                            </button>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _tasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchQuery = string.Empty;

    // Move state
    private int? _movingTaskId;

    // Add-task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);
    private bool _saving;
    private string? _addError;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        _tasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status)
    {
        var column = _tasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(_searchQuery))
        {
            column = column.Where(t =>
                t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase));
        }

        return column.ToList();
    }

    private static string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        _movingTaskId = taskId;

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = _tasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                _tasks[idx] = _tasks[idx] with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
        finally
        {
            _movingTaskId = null;
        }
    }

    private void StartAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
        _addError = null;
    }

    private void CancelAdd()
    {
        _addingToColumn = null;
        _addError = null;
    }

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
        {
            _addError = "Title is required.";
            return;
        }

        _saving = true;
        _addError = null;

        try
        {
            var created = await TaskService.CreateTaskAsync(
                _newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);

            // CreateTaskAsync returns the task with a default status; override to match the target column
            var taskInColumn = created with { Status = _addingToColumn! };

            // If the service already set the correct status, use as-is; otherwise move it
            if (created.Status != _addingToColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, _addingToColumn!);
            }

            _tasks.Add(taskInColumn);
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _addError = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }
}

namespace sv_31578d42d1c04c53bf3fc92de3808ed5.Services;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

