+@code {
+    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _tasks = new();
+    private bool _loading = true;
+    private string? _error;
+    private string _searchQuery = string.Empty;
+
+    // Move state
+    private int? _movingTaskId;
+
+    // Add-task form state
+    private string? _addingToColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+    private bool _saving;
+    private string? _addError;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasksAsync();
+    }
+
+    private async Task LoadTasksAsync()
+    {
+        _loading = true;
+        _error = null;
+
+        try
+        {
+            _tasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private List<TaskItem> GetColumnTasks(string status) =>
+        _tasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredColumnTasks(string status)
+    {
+        var column = _tasks.Where(t => t.Status == status);
+
+        if (!string.IsNullOrWhiteSpace(_searchQuery))
+        {
+            column = column.Where(t =>
+                t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase));
+        }
+
+        return column.ToList();
+    }
+
+    private static string GetPriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        _movingTaskId = taskId;
+
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _tasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                _tasks[idx] = _tasks[idx] with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to move task: {ex.Message}";
+        }
+        finally
+        {
+            _movingTaskId = null;
+        }
+    }
+
+    private void StartAdd(string column)
+    {
+        _addingToColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+        _addError = null;
+    }
+
+    private void CancelAdd()
+    {
+        _addingToColumn = null;
+        _addError = null;
+    }
+
+    private async Task SaveNewTaskAsync()
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle))
+        {
+            _addError = "Title is required.";
+            return;
+        }
+
+        _saving = true;
+        _addError = null;
+
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(
+                _newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
+
+            // CreateTaskAsync returns the task with a default status; override to match the target column
+            var taskInColumn = created with { Status = _addingToColumn! };
+
+            // If the service already set the correct status, use as-is; otherwise move it
+            if (created.Status != _addingToColumn)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, _addingToColumn!);
+            }
+
+            _tasks.Add(taskInColumn);
+            _addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _addError = $"Failed to create task: {ex.Message}";
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
